// Fictional records; every displayed finding uses shared analytics.
export function demoData(){let next=1,known=[];return Array.from({length:28},(_,i)=>{const recent=i>=25,special=i===17,type=special?'Competition':recent?'Presentation':['Workshop','Discussion','Interactive Activity','Presentation'][i%4],attendance=special?82:recent?[18,16,14][i-25]:{Workshop:37,Discussion:31,'Interactive Activity':39,Presentation:25}[type]+(i%3-1)*2;const newCount=i===0?attendance:recent?9:special?44:5+i%3;const returning=attendance-newCount,members=known.slice(-returning);while(members.length<attendance){const id='M'+String(next++).padStart(3,'0');members.push(id);known.push(id)}return{id:'demo-'+i,date:new Date(Date.UTC(2026,0,8+i*7)).toISOString().slice(0,10),name:special?'Campus sports challenge':recent?['Season review slides','Player metrics presentation','League recap'][i-25]:['Build a fantasy roster','The MVP debate','Prediction challenge','Sports analytics basics'][i%4],topic:special?'Campus sports challenge':recent?'Season review':'Sports analytics',attendance,type,time:i%5===0?'After school':'Lunch',promotion:recent?'Instagram':i%4===3?'Instagram':'Announcements + Instagram',reach:special?1100:recent?[160,120,100][i-25]:type==='Presentation'?300+i%3*20:480+i%5*35,days_promoted_before:recent?[1,0,1][i-25]:i%4===3?2:4+i%2,signups:recent?[12,9,8][i-25]:Math.round(attendance*.7),special_event:special,notes:special?'Fictional special event open to the whole school.':recent?'Fictional club record: presentation week.':'Fictional sample record.',new_members:newCount,returning_members:returning,members}})}
